={{ (function() {
var s = $json;
var score = s.header_score || '?';
var cat = s.category || 'other';
var title = s.title || 'Untitled';
var url = s.url || '';
var source = s.feed_name || 'RSS';
var sc = (s.source_count || 1);
var trending = sc >= 3 ? '🔥 ' + sc + ' sources\n' : '';

var catEmoji = {
  politics: '🏛',
  geopolitics: '🌍',
  science: '🔬',
  tech: '💻',
  economics: '📈',
  quirky: '✨',
  other: '📄'
};
var emoji = catEmoji[cat] || catEmoji.other;

return trending + emoji + ' ' + score + '/10 | ' + cat + '\n\n<b>' + title + '</b>\n\n📰 ' + source + '\n\n<a href="' + url + '">Read full article</a>';
})() }}

