var data = $('Prepare Presentation').first().json;
var articles = data.articles || [];
var chatIds = $('Config').first().json.CHAT_IDS || ['1240314255'];

var items = [];
for (var a = 0; a < articles.length; a++) {
  var art = articles[a];
  var urlStr = art.url || '';
  var cleanPath = urlStr.split('?')[0].split('#')[0];
  if (cleanPath.length > 30) cleanPath = cleanPath.substring(cleanPath.length - 30);

  for (var c = 0; c < chatIds.length; c++) {
    items.push({
      json: {
        title: art.title,
        url: art.url,
        category: art.category,
        header_score: art.header_score,
        source_count: art.source_count || 1,
        feed_name: art.feed_name,
        clean_path: cleanPath,
        approve_cb: 'a:' + cleanPath,
        skip_cb: 's:' + cleanPath,
        chat_id: chatIds[c]
      }
    });
  }
}
return items;

// FIX: Use workflow staticData for total_classified, not self-defeating Unpack comparison
